      <div class="portal-metrics"><div><span>DEMANDAS EM ANDAMENTO</span><strong>${String(active.length).padStart(2,'0')}</strong><small>Em diferentes etapas</small></div><div><span>AGUARDANDO SUA APROVAÇÃO</span><strong>${String(approvals.length).padStart(2,'0')}</strong><small>${approvals.length?'Sua avaliação faz diferença':'Tudo em dia!'}</small></div><div><span>ENTREGAS CONCLUÍDAS</span><strong>${String(done.length).padStart(2,'0')}</strong><small>Histórico de projetos</small></div></div>
